sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color;
uniform float alpha;
uniform float punch;
uniform float screenSpace;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    bool inside = coord.x >= 0.0 && coord.y >= 0.0 && coord.x < size.x && coord.y < size.y;
    half m = screenSpace > 0.5 || inside ? color.a * half(clamp(alpha, 0.0, 1.0)) : 0.0;
    half4 matte = half4(color.rgb * m, m);
    if (punch > 0.5) return matte * (1.0 - c.a);
    return c + matte * (1.0 - c.a);
}
